    if N <= 1:
        return str(N)

    num = 1
    den = 2 * N - 1

    while num <= N // 2:
        if N < num + num:
            return f"{num}/{den}"
        num = den
        den = 2 * num - 1

    if (N - 1) % 2:
        return f"{num + 1}/{den - 2}"
    else:
        return f"{num}/{den - 1}"

