def max_energy(beads):
    n = len(beads)

    # Create a dp array to store the maximum energy up to each element
    dp = [0] * n

    # Iterate through each element in the necklace
    for i in range(n):
        # Iterate through each previous element to find a matching head-tail pair
        for j in range(i):
            if beads[j] == beads[i]:
                # Calculate energy for the current pair
                if i == j:  # On the first element itself
                    dp[i] = beads[i] ** 3
                else:
                    dp[i] = dp[j] * dp[(i-1+j)%n] * beads[i]

    # The maximum energy is the maximum value in the dp array
    return max(dp)

