def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x or k < 1 or not 0 < x < n:
        return 0  # Invalid input checks

    # dp[i][j] represents the number of ways to partition i into j parts
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    # Base case: There's exactly one way to partition 0 into 0 parts
    dp[0][0] = 1

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(1, min(i, k) + 1):
            # Can add i to the current partitions
            if i - x >= 0:
                dp[i][j] += dp[i - x][j]
            # Can add j - 1 to the current partition (i doesn't add an extra part)
            if j - 1 >= 0:
                dp[i][j] += dp[i][j - 1]

    return dp[n][k]

