def mod_inverse(a, b):
    if b == 0:
        return None

    x0, x1 = 1, 0
    y0, y1 = 0, 1

    while b:
        q = a // b
        a, b = b, a % b

        x0, x1 = x1 - q * x0, x0
        y0, y1 = y1 - q * y1, y1

    if x0 < 0:
        x0 += b

    return x0

